import { consumeBudgets, rateLimitHttpError } from "@/lib/rate-limit";
import { auth } from "@/auth";
import { db } from "@/lib/db";
import { z } from "zod";

export async function GET(
  _request: Request,
  { params }: { params: Promise<{ id: string }> },
) {
  const headers = { "Cache-Control": "private, no-store" };
  const session = await auth();
  if (!session?.user?.id)
    return new Response("Unauthorized", { status: 401, headers });
  try {
    await consumeBudgets(session.user.id, ["export"]);
  } catch (error) {
    return (
      rateLimitHttpError(error) ??
      new Response("Unavailable", { status: 503, headers })
    );
  }
  const id = z.uuid().safeParse((await params).id);
  if (!id.success) return new Response("Not found", { status: 404, headers });
  const template = await db.template.findFirst({
    where: {
      id: id.data,
      userId: session.user.id,
      user: { deletionRequestedAt: null },
    },
    select: { id: true, name: true, subject: true, body: true },
  });
  if (!template) return new Response("Not found", { status: 404, headers });
  return new Response(JSON.stringify(template, null, 2), {
    headers: {
      "Content-Type": "application/json; charset=utf-8",
      "Content-Disposition": `attachment; filename="template-${template.id}.json"`,
      "Cache-Control": "private, no-store",
      "X-Content-Type-Options": "nosniff",
    },
  });
}
